async function listOrders(db) {
  const orders = await db.query('SELECT id FROM orders');
  const results = [];
  for (const o of orders) {
    const items = await db.query('SELECT * FROM items WHERE order_id = ' + o.id);
    results.push({ order: o, items });
  }
  return results;
}
